if (!defined('_PS_VERSION_')) {
    exit;
}

class FeedtrixLlmsModuleFrontController extends ModuleFrontController
{
    public function initContent()
    {
        $file = (string) Tools::getValue('file', 'llms');
        $page = (int) Tools::getValue('page');
        if ('full' === $file && $page > 0) {
            $file = 'full-' . $page;
        }
        if (!FeedTrixSettings::isConnected() || !FeedTrixSettings::llmsEnabled() || null === FeedTrixLlms::apiPath($file)) {
            FeedTrixResponse::text(404, "Not found\n", ['Cache-Control' => 'no-store', 'X-Generator' => 'FeedTrix']);
        }
        FeedTrixBotTracker::record('llms_txt');

        $missing = false;
        $content = FeedTrixLlms::content($file, $missing);
        if ($missing) {
            FeedTrixResponse::text(404, "Not found\n", ['X-Generator' => 'FeedTrix']);
        }
        if (null === $content) {
            FeedTrixResponse::text(503, "Temporarily unavailable\n", ['Retry-After' => '300', 'X-Generator' => 'FeedTrix']);
        }
        FeedTrixResponse::text(200, $content, ['X-Generator' => 'FeedTrix', 'Cache-Control' => 'public, max-age=300']);
    }
}
